from playwright.sync_api import sync_playwright
def ok(n,c): print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch()
    for name,vw in (('phone390',390),('phone320',320),('desktop',1100)):
        ctx=b.new_context(service_workers='block',viewport={'width':vw,'height':844}); pg=ctx.new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
        pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file','/home/claude/Transactions.csv'); pg.wait_for_selector('#setup',timeout=20000)
        ok(name+': version 16.3', pg.evaluate("(async()=>(await import('/js/version.js')).versionText())()").startswith('16.'))
        for tab in ('analytics','outlook'):
            pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(800); pg.goto('http://localhost:8123/#/'+tab); pg.wait_for_timeout(1200)
            h=pg.evaluate("(()=>{const bb=document.querySelector('[data-act=nav-back]').getBoundingClientRect(),t=document.querySelector('header.top h1').getBoundingClientRect();return {b:[bb.right,bb.top,bb.bottom],t:[t.left,t.top,t.bottom],burger:!!document.querySelector('header.top .burger')}})()")
            ok(name+': '+tab+' back arrow left of title, aligned', 0<=h['t'][0]-h['b'][0]<12 and abs((h['b'][1]+h['b'][2])/2-(h['t'][1]+h['t'][2])/2)<3 and not h['burger'])
            pg.click('[data-act=nav-back]'); pg.wait_for_timeout(500)
            ok(name+': '+tab+' back returns to Home', pg.evaluate("location.hash")=='#/home')
        pg.goto('http://localhost:8123/#/analytics'); pg.wait_for_timeout(1500)
        ok(name+': no stray dot at the top', pg.evaluate("document.querySelectorAll('.dot').length")==0 or pg.evaluate("![...document.querySelectorAll('.dot')].some(e=>getComputedStyle(e).position==='absolute'&&e.closest('.hint'))"))
        a=pg.evaluate("(()=>{const g=[...document.querySelectorAll('.t1a .t1seg')];return {n:g.map(x=>x.querySelectorAll('button').length),sel:g.map(x=>x.dataset.sel),over:document.documentElement.scrollWidth>innerWidth,labels:g.map(x=>[...x.querySelectorAll('button')].map(b=>b.textContent))}})()")
        print(a)
        ok(name+': period switch uses t1seg (4+4), 30 days chosen, no overflow', a['n']==[4,4] and a['sel']==['1','-1'] and not a['over'])
        pg.click('.t1a .t1s-slot:has-text("This year")'); pg.wait_for_timeout(500)
        ok(name+': choosing another period works', pg.evaluate("[...document.querySelectorAll('.t1a .t1seg')].map(x=>x.dataset.sel).join()")=='-1,2')
        pg.click('.t1a .t1s-slot:has-text("30 days")'); pg.wait_for_timeout(400)
        for id_ in ('an-cf','an-nw'):
            pg.evaluate("id=>{const c=document.querySelector('[data-act=coll][data-id=%s], #%s');}"%(id_,id_) if False else "1")
        pg.evaluate("document.querySelectorAll('.coll').forEach(c=>{if(c.classList.contains('closed')||!c.open&&c.tagName==='DETAILS')c.open=true})")
        g=pg.evaluate("[...document.querySelectorAll('svg.t1line')].map(s=>({line:!!s.querySelector('.t1l'),dot:!!s.querySelector('.t1dot'),op:s.querySelector('stop').getAttribute('stop-opacity'),filt:getComputedStyle(s.querySelector('.t1l')).filter!=='none'}))")
        print(g)
        ok(name+': both graphs use the Home-style line (smooth, end marker, stronger fill)', len(g)==2 and all(x['line'] and x['dot'] and float(x['op'])>.3 for x in g))
        ok(name+': no errors %s'%errs, not errs)
        pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1500)
        c=pg.evaluate("(()=>{const q=s=>document.querySelector(s),r=e=>e.getBoundingClientRect(),a=r(q('.avgcard')),n=r(q('.t1chips')),ch=[...document.querySelectorAll('.t1chip')].map(r);return {h:Math.round(a.height),gap:Math.round(n.top-a.bottom),labels:[...document.querySelectorAll('.t1chip')].map(e=>e.textContent),hh:ch.map(x=>Math.round(x.height)),tops:ch.map(x=>Math.round(x.top)),left:Math.round(ch[0].left-a.left),right:Math.round(a.right-ch[1].right),over:document.documentElement.scrollWidth>innerWidth,legacyBtn:document.querySelectorAll('.t1chips button').length}})()")
        print(c)
        ok(name+': average card compact (<=104px, was ~118; a 320px phone must wrap)', c['h']<=(104 if vw>=390 else 150))
        ok(name+': chips right under the card, same row, equal height, aligned with card edges', c['labels']==['Outlook','Analytics'] and c['gap']<=14 and c['tops'][0]==c['tops'][1] and c['hh'][0]==c['hh'][1]<=36 and abs(c['left']-c['right'])<=1 and not c['over'])
        pg.click('.t1chip:has-text("Analytics")'); pg.wait_for_timeout(600)
        ok(name+': chip opens Analytics', pg.evaluate("location.hash")=='#/analytics')
        ctx.close()
    ctx=b.new_context(service_workers='block',viewport={'width':390,'height':844}); pg=ctx.new_page()
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached'); pg.set_input_files('#first-file','/home/claude/Transactions.csv'); pg.wait_for_selector('#setup',timeout=20000)
    pg.evaluate("localStorage.setItem('sukli-look', JSON.stringify({design:'legacy'}))"); pg.reload(); pg.wait_for_timeout(1200)
    pg.goto('http://localhost:8123/#/analytics'); pg.wait_for_timeout(1500)
    ok('legacy analytics: old seg switch, burger header, old line', pg.evaluate("!!document.querySelector('.afilters .seg.sm')&&!document.querySelector('.t1a')&&!!document.querySelector('header.top .burger')&&!document.querySelector('.t1line')"))
    pg.goto('http://localhost:8123/#/home'); pg.wait_for_timeout(1200)
    ok('legacy home: no chips', pg.evaluate("getComputedStyle(document.querySelector('.t1chips')||document.body).display")in('none','block') and pg.evaluate("[...document.querySelectorAll('.t1chips')].every(e=>getComputedStyle(e).display==='none')"))
